vector<int> bfs(int n, vector<vector<int>>& g, int src) {
    vector<int> dist(n, -1);
    queue<int> q;
    dist[src] = 0; q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : g[u]) if (dist[v] < 0) {
            dist[v] = dist[u] + 1; q.push(v);
        }
    }
    return dist;
}

