static int[] bfs(List<List<Integer>> g, int src) {
        int n = g.size();
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        dist[src] = 0; q.add(src);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g.get(u)) if (dist[v] < 0) {
                dist[v] = dist[u] + 1; q.add(v);
            }
        }
        return dist;
}

