func bfs(g [][]int, src int) []int {
    n := len(g)
    dist := make([]int, n)
    for i := range dist { dist[i] = -1 }
    q := []int{src}
    dist[src] = 0
    for len(q) > 0 {
        u := q[0]; q = q[1:]
        for _, v := range g[u] {
            if dist[v] < 0 {
                dist[v] = dist[u] + 1
                q = append(q, v)
            }
        }
    }
    return dist
}
